+{"connection_id":"BC-051f9b2fbb217d3f8165","ref":"Didache 1.1","status":"unavailable","reason":"Didache text is absent from this local snapshot; the proposed two-ways wording cannot be verified here.","paragraphs":[60],"evidence":[],"annotations":[]}
+{"connection_id":"BC-9f7c886236c3e2897d74","ref":"Didache 1:1","status":"unavailable","reason":"The alternate Didache locator has no local witness in this run; its opening contrast remains unverified.","paragraphs":[60],"evidence":[],"annotations":[]}
