+{"connection_id":"BC-26a5a6a2ffcf3501f4fc","ref":"SBLGNT:Matt.12.36","status":"rejected","reason":"Answering for idle words on judgment day concerns accountability, not the absence or return of persons or things.","paragraphs":[61],"evidence":["SBLGNT:Matt.12.36"],"annotations":[]}
